"""Generates the four agent-readiness artifacts from a ProductAnalysis."""

from __future__ import annotations

import json
import re
from urllib.parse import urlparse

from models import Artifacts, AuditBreakdown, AuditScore, CoreAction, ProductAnalysis

HTTP_METHODS = ("GET", "POST", "PUT", "PATCH", "DELETE")

AUTO_GENERATED_NOTE = (
    "This file was auto-generated by AgentReady and requires human review."
)

SCORE_POINTS = {
    "has_api": 20,
    "has_openapi_spec": 20,
    "has_llms_txt": 15,
    "has_structured_docs": 15,
    "has_api_key_auth": 15,
    "has_webhook_support": 15,
}


def generate_artifacts(
    analysis: ProductAnalysis,
    website_url: str | None,
    has_llms_txt: bool = False,
    blocked_ai_bots: list[str] | None = None,
) -> Artifacts:
    """Generate all four output files as strings from the structured LLM analysis."""
    return Artifacts(
        llms_txt=_generate_llms_txt(analysis, website_url),
        audit_md=_generate_audit_md(analysis, has_llms_txt, blocked_ai_bots or []),
        mcp_server_ts=_generate_mcp_server(analysis, website_url),
        openapi_yaml=_generate_openapi_yaml(analysis, website_url),
    )


def compute_audit_score(analysis: ProductAnalysis, has_llms_txt: bool = False) -> AuditScore:
    """
    Score the product's agent-readiness out of 100 using the fixed rubric.

    `has_llms_txt` comes from actually fetching /llms.txt (or finding it in the repo),
    not from the LLM.
    """
    breakdown = AuditBreakdown(
        has_api=bool(analysis.core_actions),
        has_openapi_spec=analysis.has_existing_openapi,
        has_llms_txt=has_llms_txt,
        has_structured_docs=analysis.has_existing_docs,
        has_api_key_auth=analysis.auth_method == "api_key",
        has_webhook_support=analysis.webhook_support,
    )
    score = sum(points for check, points in SCORE_POINTS.items() if getattr(breakdown, check))
    return AuditScore(total=100, score=score, breakdown=breakdown)


def _generate_llms_txt(analysis: ProductAnalysis, website_url: str | None) -> str:
    lines = [
        f"# {analysis.product_name}",
        "",
        f"> {analysis.product_description}",
        "",
        f"Category: {analysis.product_category}",
        "",
        "## Key Actions",
    ]

    if analysis.core_actions:
        for action in analysis.core_actions:
            method = action.http_method if action.http_method != "UNKNOWN" else "?"
            endpoint = action.endpoint if action.endpoint != "UNKNOWN" else "(endpoint unknown)"
            lines.append(f"- {action.name}: {method} {endpoint} — {action.description}")
    else:
        lines.append("- No specific actions were detected. Add route-level docs for agents.")

    lines += [
        "",
        "## Authentication",
        f"Method: {analysis.auth_method}",
    ]

    if website_url:
        lines += ["", "## Links", f"Docs / Website: {website_url}"]

    lines += ["", "## Tech Stack", ", ".join(analysis.tech_stack) or "Not detected"]

    return "\n".join(lines) + "\n"


def _generate_audit_md(
    analysis: ProductAnalysis, has_llms_txt: bool, blocked_ai_bots: list[str]
) -> str:
    score = compute_audit_score(analysis, has_llms_txt)
    breakdown = score.breakdown

    def check_line(label: str, passed: bool, points: int) -> str:
        icon = "✅" if passed else "❌"
        return f"- {icon} **{label}** ({points} pts)"

    checks = [
        check_line("Has a public API", breakdown.has_api, SCORE_POINTS["has_api"]),
        check_line(
            "Has an OpenAPI/Swagger spec", breakdown.has_openapi_spec, SCORE_POINTS["has_openapi_spec"]
        ),
        check_line("Has llms.txt", breakdown.has_llms_txt, SCORE_POINTS["has_llms_txt"]),
        check_line(
            "Has structured docs", breakdown.has_structured_docs, SCORE_POINTS["has_structured_docs"]
        ),
        check_line(
            "Has API key / token auth", breakdown.has_api_key_auth, SCORE_POINTS["has_api_key_auth"]
        ),
        check_line(
            "Has webhook support", breakdown.has_webhook_support, SCORE_POINTS["has_webhook_support"]
        ),
    ]

    working = [c for c in checks if "✅" in c] or ["- Nothing scored yet — this product is early-stage for agents."]
    missing = analysis.missing_agent_features or ["No specific gaps were identified."]
    recommendations = analysis.recommendations or ["No specific recommendations were generated."]
    priority = recommendations[:3]

    lines = [
        "# Agent-Readiness Audit",
        "",
        f"**Score: {score.score} / {score.total}**",
        "",
        "## What's Working",
        *working,
        "",
        "## What's Missing",
        *[f"- {item}" for item in missing],
        "",
        *_crawler_access_section(blocked_ai_bots),
        "## Action Items",
        *[f"{i}. {item}" for i, item in enumerate(recommendations, start=1)],
        "",
        "## Priority Fixes",
        *[f"{i}. {item}" for i, item in enumerate(priority, start=1)],
        "",
        "---",
        f"*{AUTO_GENERATED_NOTE}*",
    ]

    return "\n".join(lines) + "\n"


def _crawler_access_section(blocked_ai_bots: list[str]) -> list[str]:
    if not blocked_ai_bots:
        return []
    return [
        "## AI Crawler Access",
        "Your robots.txt blocks these AI crawlers from your homepage:",
        *[f"- `{bot}`" for bot in blocked_ai_bots],
        "",
        "Blocking training crawlers (GPTBot, CCBot, Google-Extended) is a valid choice. Blocking "
        "answer/search bots (OAI-SearchBot, ChatGPT-User, PerplexityBot, Claude-User) means AI "
        "assistants can't read your site when users ask about you.",
        "",
    ]


def _path_params(endpoint: str) -> tuple[str, list[str]]:
    """Normalize `/items/:id` to `/items/{id}` and return (path, param_names)."""
    path = re.sub(r":([A-Za-z_]\w*)", r"{\1}", endpoint)
    return path, re.findall(r"\{([A-Za-z_]\w*)\}", path)


def _known_endpoint(action: CoreAction) -> bool:
    return action.endpoint.startswith("/") and action.http_method in HTTP_METHODS


def _ts_tool(action: CoreAction) -> str:
    name = json.dumps(action.name)
    description = json.dumps(action.description)

    if not _known_endpoint(action):
        return f"""server.registerTool(
  {name},
  {{
    description: {description},
    inputSchema: {{
      // TODO: define input fields
    }},
  }},
  async () => {{
    // TODO: endpoint and method could not be inferred — implement the call.
    throw new Error("Not implemented");
  }}
);"""

    path, params = _path_params(action.endpoint)
    has_body = action.http_method in ("POST", "PUT", "PATCH")
    fields = [
        f"      {p}: z.string().describe({json.dumps(p + ' path parameter')}),"
        for p in params
    ]
    if has_body:
        fields.append(
            "      body: z.record(z.string(), z.unknown()).optional()"
            '.describe("JSON request body"),'
        )
    if not fields:
        fields.append("      // TODO: add query parameters if this endpoint takes any")

    args = ", ".join(params + (["body"] if has_body else []))
    handler_args = f"{{ {args} }}" if args else ""
    url_expr = "`" + re.sub(r"\{(\w+)\}", r"${encodeURIComponent(\1)}", path) + "`"
    body_arg = ", body" if has_body else ""

    return f"""server.registerTool(
  {name},
  {{
    description: {description},
    inputSchema: {{
{chr(10).join(fields)}
    }},
  }},
  async ({handler_args}) => {{
    const data = await callApi({json.dumps(action.http_method)}, {url_expr}{body_arg});
    return {{ content: [{{ type: "text", text: JSON.stringify(data, null, 2) }}] }};
  }}
);"""


def _auth_header_ts(auth_method: str) -> str:
    if auth_method in ("api_key", "jwt", "oauth2"):
        return (
            "  // Some APIs expect an `X-API-Key` header instead — check the docs.\n"
            "  if (API_KEY) headers.Authorization = `Bearer ${API_KEY}`;"
        )
    if auth_method == "basic_auth":
        return (
            "  if (API_KEY) {\n"
            '    headers.Authorization = `Basic ${Buffer.from(API_KEY).toString("base64")}`;\n'
            "  }"
        )
    return f"  // Auth method: {auth_method} — add headers here if the API needs them."


def _generate_mcp_server(analysis: ProductAnalysis, website_url: str | None) -> str:
    tools = [_ts_tool(action) for action in analysis.core_actions]
    tools_block = (
        "\n\n".join(tools) if tools else "// TODO: no actions were detected — add tools manually"
    )

    return f"""/**
 * {analysis.product_name} — MCP Server Scaffold
 *
 * {AUTO_GENERATED_NOTE}
 *
 * Install:
 *   npm install @modelcontextprotocol/sdk zod
 *
 * Run:
 *   API_BASE_URL=https://api.example.com API_KEY=... npx tsx mcp_server.ts
 */

import {{ McpServer }} from "@modelcontextprotocol/sdk/server/mcp.js";
import {{ StdioServerTransport }} from "@modelcontextprotocol/sdk/server/stdio.js";
import {{ z }} from "zod";

const API_BASE_URL = process.env.API_BASE_URL ?? {json.dumps(_server_url(website_url))};
const API_KEY = process.env.API_KEY;

async function callApi(method: string, path: string, body?: unknown): Promise<unknown> {{
  const headers: Record<string, string> = {{ Accept: "application/json" }};
{_auth_header_ts(analysis.auth_method)}
  if (body !== undefined) headers["Content-Type"] = "application/json";

  const response = await fetch(`${{API_BASE_URL}}${{path}}`, {{
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  }});
  if (!response.ok) {{
    const detail = await response.text();
    throw new Error(`${{method}} ${{path}} failed: ${{response.status}} ${{detail}}`);
  }}
  const text = await response.text();
  try {{
    return JSON.parse(text);
  }} catch {{
    return text;
  }}
}}

const server = new McpServer({{
  name: {json.dumps(_slug(analysis.product_name))},
  version: "0.1.0",
}});

{tools_block}

async function main(): Promise<void> {{
  await server.connect(new StdioServerTransport());
}}

main().catch((error) => {{
  console.error(error);
  process.exit(1);
}});
"""


def _generate_openapi_yaml(analysis: ProductAnalysis, website_url: str | None) -> str:
    paths: dict[str, dict[str, CoreAction]] = {}
    skipped: list[str] = []
    for action in analysis.core_actions:
        if not _known_endpoint(action):
            skipped.append(action.name)
            continue
        path, _ = _path_params(action.endpoint)
        paths.setdefault(path, {}).setdefault(action.http_method.lower(), action)

    path_lines: list[str] = []
    for path, methods in paths.items():
        path_lines.append(f"  {json.dumps(path)}:")
        _, params = _path_params(path)
        for method, action in methods.items():
            path_lines += [
                f"    {method}:",
                f"      operationId: {json.dumps(action.name)}",
                f"      summary: {json.dumps(action.description)}",
                "      x-inferred: true",
            ]
            if params:
                path_lines.append("      parameters:")
                for param in params:
                    path_lines += [
                        f"        - name: {param}",
                        "          in: path",
                        "          required: true",
                        "          schema:",
                        "            type: string",
                    ]
            path_lines += [
                "      responses:",
                "        '200':",
                "          description: Successful response",
            ]

    paths_block = "\n".join(path_lines) if path_lines else "  {}"
    skipped_note = (
        "# Actions with no inferable endpoint (add manually): " + ", ".join(skipped) + "\n"
        if skipped
        else ""
    )

    return f"""# ⚠️ This spec was auto-generated and requires human review
{skipped_note}openapi: 3.0.0
info:
  title: {json.dumps(analysis.product_name)}
  description: {json.dumps(analysis.product_description)}
  version: 0.1.0
servers:
  - url: {json.dumps(_server_url(website_url))}
paths:
{paths_block}
"""


def _server_url(website_url: str | None) -> str:
    if not website_url:
        return "https://api.example.com"
    parsed = urlparse(website_url)
    return f"{parsed.scheme}://{parsed.netloc}"


def _slug(name: str) -> str:
    return "".join(c.lower() if c.isalnum() else "-" for c in name).strip("-") or "agent-server"
